beforeExample:
package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.internal.corext.util.JavaModelUtil;

public class TestClass {
    public void processCompilationUnit(ICompilationUnit input) {
        if (JavaModelUtil.PACKAGE_INFO_JAVA.equals(input.getElementName())) {
            System.out.println("It's package-info.java");
        } else {
            System.out.println("It's not package-info.java");
        }
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.internal.corext.util.JavaModelUtil;

public class TestClass {
    public void processCompilationUnit(ICompilationUnit input) {
        if (JavaModelUtil.isPackageInfo((ICompilationUnit) input)) {
            System.out.println("It's package-info.java");
        } else {
            System.out.println("It's not package-info.java");
        }
    }
}

