package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.internal.corext.util.JavaModelUtil;

public class TestClass {
    public void processElement(IJavaElement input) {
        if ("someOtherFile.java".equals(input.getElementName())) { 
            System.out.println("Some other file");
        }

        String myFileName = "MyClass.java";
        if (myFileName.equals(input.getElementName())) { 
            System.out.println("My class file");
        }
    }
}
